-- Table 14-5.01 re-delivered by Biostatistics: version 2.
-- Version 1 counted every adverse event record (TRTEMFL ignored, a demo scenario).
-- Version 2 counts treatment-emergent events only (ADAE.TRTEMFL = 'Y'), as the SAP says.
-- The data (adam_adae) is unchanged; only the derivation rule changes. One statement, one new Delta version.
INSERT OVERWRITE sean_zhang_catalog.rnd_csr_pod.tlf_14_5_01_teae SELECT u.row_key, u.row_label, CAST(row_number() OVER (ORDER BY u.soc, u.lvl, u.total_n DESC, u.pt) AS INT) AS row_order, u.pbo_n AS pbo_n, round(CAST(100.0 * u.pbo_n / d.pbo_n AS DECIMAL(38,10)), 1) AS pbo_pct, u.low_n AS low_n, round(CAST(100.0 * u.low_n / d.low_n AS DECIMAL(38,10)), 1) AS low_pct, u.high_n AS high_n, round(CAST(100.0 * u.high_n / d.high_n AS DECIMAL(38,10)), 1) AS high_pct, u.total_n AS total_n, round(CAST(100.0 * u.total_n / d.total_n AS DECIMAL(38,10)), 1) AS total_pct FROM (
SELECT 'any_body_system' AS row_key, 'Any body system' AS row_label, '' AS soc, 0 AS lvl, '' AS pt, CAST(count(distinct e.USUBJID) FILTER (WHERE e.TRTA = 'Placebo') AS INT) AS pbo_n, CAST(count(distinct e.USUBJID) FILTER (WHERE e.TRTA = 'Xanomeline Low Dose') AS INT) AS low_n, CAST(count(distinct e.USUBJID) FILTER (WHERE e.TRTA = 'Xanomeline High Dose') AS INT) AS high_n, CAST(count(distinct e.USUBJID) AS INT) AS total_n FROM sean_zhang_catalog.rnd_csr_pod.adam_adae e WHERE e.TRTEMFL = 'Y' 
UNION ALL
SELECT lower(regexp_replace(regexp_replace(e.AEBODSYS, '[^A-Za-z0-9]+', '_'), '^_|_$', '')) AS row_key, initcap(lower(e.AEBODSYS)) AS row_label, e.AEBODSYS AS soc, 1 AS lvl, '' AS pt, CAST(count(distinct e.USUBJID) FILTER (WHERE e.TRTA = 'Placebo') AS INT) AS pbo_n, CAST(count(distinct e.USUBJID) FILTER (WHERE e.TRTA = 'Xanomeline Low Dose') AS INT) AS low_n, CAST(count(distinct e.USUBJID) FILTER (WHERE e.TRTA = 'Xanomeline High Dose') AS INT) AS high_n, CAST(count(distinct e.USUBJID) AS INT) AS total_n FROM sean_zhang_catalog.rnd_csr_pod.adam_adae e WHERE e.TRTEMFL = 'Y' GROUP BY e.AEBODSYS
UNION ALL
SELECT concat('pt_', lower(regexp_replace(regexp_replace(e.AEDECOD, '[^A-Za-z0-9]+', '_'), '^_|_$', ''))) AS row_key, concat(initcap(lower(e.AEDECOD)), ' (', initcap(lower(e.AEBODSYS)), ')') AS row_label, e.AEBODSYS AS soc, 2 AS lvl, e.AEDECOD AS pt, CAST(count(distinct e.USUBJID) FILTER (WHERE e.TRTA = 'Placebo') AS INT) AS pbo_n, CAST(count(distinct e.USUBJID) FILTER (WHERE e.TRTA = 'Xanomeline Low Dose') AS INT) AS low_n, CAST(count(distinct e.USUBJID) FILTER (WHERE e.TRTA = 'Xanomeline High Dose') AS INT) AS high_n, CAST(count(distinct e.USUBJID) AS INT) AS total_n FROM sean_zhang_catalog.rnd_csr_pod.adam_adae e WHERE e.TRTEMFL = 'Y' GROUP BY e.AEBODSYS, e.AEDECOD
) u CROSS JOIN (SELECT count(*) FILTER (WHERE TRT01P = 'Placebo') AS pbo_n, count(*) FILTER (WHERE TRT01P = 'Xanomeline Low Dose') AS low_n, count(*) FILTER (WHERE TRT01P = 'Xanomeline High Dose') AS high_n, count(*) AS total_n FROM sean_zhang_catalog.rnd_csr_pod.adam_adsl WHERE SAFFL = 'Y') d
